-- app/migrations/2026-11-25_task_seed_3.sql: everything outstanding into the Work queue before the holiday (Jason, 2026-11-24: "Push
-- anything outstanding into the task que so I can review it when I return"), each task linking its own docs in its source. Data only,
-- no CREATE (the runner clears a file whose tables all exist unrun, #284): new tasks once, the docs added to existing tasks' source.
INSERT INTO control_gauge_tasks (at, tz, gauge, item, kind, what, bucket, value, who, uid, why, source, goal, in_scope, out_scope, done_when, priority) SELECT UTC_TIMESTAMP(), '', 'area:control-board', 'The migration runner: a data migration is never cleared as already there unrun', 'fix', 'The migration runner: a data migration is never cleared as already there unrun', 'task', '', 'the queue''s seed', 0, '#284''s seed was logged "already there" and deleted unrun because the table it created existed: a silent false success (CLAUDE.md: no action claims success without a real check)', 'handoffs/task-seed.md (#284 and task-seed-2) · app/lib/DbUpdates.php autoRun and all()', 'A file counts as run only by its own db_updates_log entry, never because its tables exist', 'DbUpdates::autoRun and all()''s state, and the zip check refusing such a file', NULL, '#284''s case runs on the bench, and 0162 has its note', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM control_gauge_tasks WHERE kind = 'fix' AND gauge = 'area:control-board' AND item = 'The migration runner: a data migration is never cleared as already there unrun');
INSERT INTO control_gauge_task_adrs (task_id, adr, at, who) SELECT t.id, '0162', UTC_TIMESTAMP(), 'the queue''s seed' FROM control_gauge_tasks t WHERE t.kind = 'fix' AND t.gauge = 'area:control-board' AND t.item = 'The migration runner: a data migration is never cleared as already there unrun' AND NOT EXISTS (SELECT 1 FROM control_gauge_task_adrs x WHERE x.task_id = t.id AND x.adr = '0162' AND x.removed_at IS NULL);
